css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .78); position: relative; }
.loader .tin { position: absolute; left: 14%; right: 14%; bottom: 6%; height: 30%; border-radius: 4px 4px 10px 10px; background: linear-gradient(#94a3b8, #475569); }
.loader .dough { position: absolute; left: 18%; right: 18%; bottom: 30%; height: 12%; border-radius: 46% 46% 12% 12% / 70% 70% 12% 12%; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent-2)), var(--accent)); animation: dough-proof calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader i { position: absolute; width: 6%; height: 6%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: dough-flour calc(var(--loader-speed) * 3) ease-out infinite; }
.loader i:nth-of-type(1) { left: 24%; bottom: 60%; }
.loader i:nth-of-type(2) { left: 50%; bottom: 68%; animation-delay: calc(var(--loader-speed) * 1); }
.loader i:nth-of-type(3) { left: 72%; bottom: 62%; animation-delay: calc(var(--loader-speed) * 2); }
@keyframes dough-proof { 0%, 8% { height: 12%; } 60%, 82% { height: 46%; } 98%, 100% { height: 12%; } }
@keyframes dough-flour { 0% { opacity: 0; transform: translateY(40%) scale(.5); } 25% { opacity: .8; } 100% { opacity: 0; transform: translateY(-70%) scale(1.2); } }
